#include <stdio.h>
struct Rec { int id; double v; };
int main(void) {
    struct Rec a[3] = {{1,1.5},{2,2.5},{3,3.5}};
    FILE *w = fopen("b.dat", "wb");
    fwrite(a, sizeof(struct Rec), 3, w);
    fclose(w);
    struct Rec b[3];
    FILE *r = fopen("b.dat", "rb");
    size_t n = fread(b, sizeof(struct Rec), 3, r);
    fclose(r);
    printf("read %zu records\n", n);
    for (size_t i = 0; i < n; i++) printf("id=%d v=%.1f\n", b[i].id, b[i].v);
    return 0;
}
